func (c *Client) TrailsEnabled(ctx context.Context, forge, owner, repo string) (bool, error) {
	query := "limit=1"
	if c.TrailBackend() == "entire-api" {
		query = "pageSize=1"
	}
	resp, err := c.Get(ctx, fmt.Sprintf("/api/v1/trails/%s/%s/%s?%s",
