	BodyDocument       *TrailBodyDocument `json:"bodyDocument,omitempty"`
}

func (r *TrailResource) UnmarshalJSON(data []byte) error {
	type plain TrailResource
	if err := decodeNormalizedTrailJSON(data, (*plain)(r)); err != nil {
