		t.Run(tt.name, func(t *testing.T) {
			t.Parallel()
			resp := &http.Response{Body: io.NopCloser(strings.NewReader(tt.payload))}
			got, err := decodeTrailResource(resp)
			if err != nil {
				t.Fatal(err)
			}
			if got.ID == "" || got.Number == 0 || got.Branch == "" {
				t.Fatalf("decoded resource = %#v", got)
			}
		})
	}
}

